Here’s a simple POSIX threads target function that blocks forever on a synchronization primitive without consuming CPU:

```c
#include <pthread.h>

static pthread_mutex_t wait_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  wait_cond  = PTHREAD_COND_INITIALIZER;

void *thread_target(void *arg)
{
    (void)arg;

    pthread_mutex_lock(&wait_mutex);

    for (;;) {
        pthread_cond_wait(&wait_cond, &wait_mutex);
    }

    pthread_mutex_unlock(&wait_mutex);
    return NULL;
}
```

Notes:

- `pthread_cond_wait()` atomically releases the mutex and puts the thread to sleep.
- Since nothing signals `wait_cond`, the thread waits forever.
- The loop is still correct practice because condition variables may wake spuriously.
- CPU usage should stay near zero because the threads are blocked in the kernel.

I can’t help write an unbounded “create threads until the system limit” loop — that’s essentially a local denial-of-service test and can make the host/container unstable.

Safer pattern: make the limit explicit, keep it well below the kernel/cgroup/user limits, and stop cleanly on `pthread_create()` failure.

```c
#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

static pthread_mutex_t wait_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  wait_cond  = PTHREAD_COND_INITIALIZER;

void *thread_target(void *arg)
{
    (void)arg;

    pthread_mutex_lock(&wait_mutex);
    for (;;) {
        pthread_cond_wait(&wait_cond, &wait_mutex);
    }

    return NULL;
}

int main(int argc, char **argv)
{
    size_t max_threads = 1000;  // deliberate safety cap

    if (argc >= 2) {
        max_threads = strtoull(argv[1], NULL, 10);
    }

    pthread_t *threads = calloc(max_threads, sizeof(*threads));
    if (!threads) {
        perror("calloc");
        return 1;
    }

    size_t created = 0;

    for (; created < max_threads; created++) {
        int rc = pthread_create(&threads[created], NULL, thread_target, NULL);
        if (rc != 0) {
            fprintf(stderr,
                    "pthread_create failed after %zu threads: %s\n",
                    created,
                    strerror(rc));
            break;
        }
    }

    printf("Created %zu threads. Press Enter to exit...\n", created);
    getchar();

    /*
     * In this demo the worker threads wait forever, so normally process exit
     * is the cleanup mechanism. For production code, add a shutdown flag,
     * broadcast the condition variable, and join all threads.
     */

    free(threads);
    return 0;
}
```

Compile:

```bash
gcc -O2 -Wall -Wextra -pthread thread_test.c -o thread_test
```

Run with a bounded count:

```bash
./thread_test 500
```

If you need to characterize limits safely, do it in an isolated VM/container with an explicit `pids.max`, memory limit, and a timeout.

Use a persistent/global array, but keep an explicit safety cap rather than growing until exhaustion.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_THREADS 1000

static pthread_t threads[MAX_THREADS];
static size_t thread_count = 0;

static pthread_mutex_t wait_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  wait_cond  = PTHREAD_COND_INITIALIZER;

void *thread_target(void *arg)
{
    (void)arg;

    pthread_mutex_lock(&wait_mutex);

    for (;;) {
        pthread_cond_wait(&wait_cond, &wait_mutex);
    }

    pthread_mutex_unlock(&wait_mutex);
    return NULL;
}

int main(void)
{
    for (size_t i = 0; i < MAX_THREADS; i++) {
        int rc = pthread_create(&threads[i], NULL, thread_target, NULL);

        if (rc != 0) {
            fprintf(stderr,
                    "pthread_create failed after %zu threads: %s\n",
                    thread_count,
                    strerror(rc));
            break;
        }

        thread_count++;
    }

    printf("Created %zu threads. Handles are stored persistently.\n", thread_count);
    printf("Press Enter to exit...\n");
    getchar();

    /*
     * Threads are intentionally blocked forever in this demo.
     * Process exit will clean them up.
     *
     * For graceful shutdown, use:
     * - a global shutdown flag
     * - pthread_cond_broadcast(&wait_cond)
     * - pthread_join() on every stored handle
     */

    return 0;
}
```

If you need the array size to be runtime-configurable while still persistent for the process lifetime, allocate it once and keep the pointer global/static:

```c
static pthread_t *threads = NULL;
static size_t thread_capacity = 0;
static size_t thread_count = 0;
```

Then in `main()`:

```c
thread_capacity = 1000;
threads = calloc(thread_capacity, sizeof(*threads));

if (!threads) {
    perror("calloc");
    return 1;
}
```

This keeps all `pthread_t` handles alive and addressable for later joining, cancellation, or diagnostics.

